import { date } from 'quasar';
import { defineStore } from 'pinia';
import { asnApiService } from 'src/services';
import { useSettingStore } from 'src/store/main';
import { shipmentApiService } from 'src/services';
export interface dynamicObj {
  [key: string]: any;
}
import { removeSortOrderFromStorage } from 'src/utils/ms_utlis';

export const useDashboardShipmentStore = defineStore(
  'dashboard_shipment_store',
  {
    state: () => ({
      pagination_size_key: 'PAGINATION_SIZE',
      pagination_size: 10,
      paginationCount: 0,
      total_data: 0,
      loading: true,
      display_data: [] as any[],
      order_by: {} as dynamicObj,
      pagination: {
        current_page: 1,
        total_pages: 0,
        page_size: 25,
      },
      params: {
        item_id: '',
        purchase_order: '',
        status: '',
        shipped_quantity: '',
        delivery_number: '',
        location_id: '',
      },
      sort_column: {
        sort_by: '',
        order: '',
      },
      table_columns: {
        item_id: {
          name: 'item_id',
          translation_key: 'item_id',
          actions: true,
          order: 0,
          align: 'left',
        },
        line_number: {
          name: 'line_number',
          translation_key: 'line_number',
          actions: true,
          order: 1,
          align: 'center',
        },
        purchase_order: {
          name: 'purchase_order',
          translation_key: 'po_number',
          actions: true,
          order: 2,
          align: 'left',
        },
        status: {
          name: 'status',
          translation_key: 'status',
          actions: true,
          order: 3,
          align: 'left',
        },
        shipped_quantity: {
          name: 'shipped_quantity',
          translation_key: 'shipped_quantity',
          actions: true,
          order: 4,
          align: 'center',
        },
        delivery_number: {
          name: 'delivery_number',
          translation_key: 'delivery_number',
          actions: true,
          order: 5,
          align: 'left',
        },
        description: {
          name: 'description',
          translation_key: 'description',
          actions: true,
          order: 6,
          align: 'left',
        },
        location_id: {
          name: 'location_id',
          translation_key: 'warehouse_id',
          actions: true,
          order: 7,
          align: 'left',
        },
      } as dynamicObj,
    }),
    actions: {
      resetPagination() {
        this.pagination = {
          current_page: 1,
          total_pages: 0,
          page_size: 25,
        };
      },
      resetFilter() {
        ((this.params = {
          item_id: '',
          purchase_order: '',
          status: '',
          shipped_quantity: '',
          delivery_number: '',
          location_id: '',
        }),
          (this.sort_column = {
            sort_by: '',
            order: '',
          }),
          (this.pagination = {
            current_page: 1,
            total_pages: 0,
            page_size: 25,
          }),
          removeSortOrderFromStorage('supplier'),
          (this.order_by = {} as dynamicObj));
      },
      async getColumnPreference(master_lookup_type: string) {
        const key = 'master_data' + master_lookup_type;
        const settings_store = useSettingStore();
        const setting = await settings_store.getSetting(key) as dynamicObj;
        return String(!setting ? '[]' : setting);
      },
      async getAsnData() {
        try {
          this.loading = true;
          const filterObj: any = {};
          for (const [key, value] of Object.entries(this.params)) {
            const data = value as any;
            if (typeof data === 'object') {
              if (data && Object.keys(data).length > 0) {
                filterObj[key] = data.value;
                logInfo(data.value);
              }
            } else if (data !== '') {
              filterObj[key] = data;
            }
          }
          const offset =
            (this.pagination.current_page - 1) * this.pagination.page_size;
          const queryParam: { [key: string]: string | number } = {
            amounts_format: 'en_US',
            limit: this.pagination.page_size,
            skip: offset,
            sort: this.sort_column.sort_by,
            sort_direction: this.sort_column.order,
            ...filterObj,
          };

          // const filterByFields: { [key: string]: any } = {'fields':filterObj};

          const response =
            await shipmentApiService.getReceiveDeliveryEndpoint(queryParam);
          if (!response) {
            throw response;
          }
          this.display_data = response?.data as any[];
          this.paginationCount = response?.records;
          this.pagination.total_pages = Math.ceil(
            response.records / this.pagination.page_size,
          );
          this.total_data = response.total_records;
          this.loading = false;
        } catch (error) {
          throw error;
        }
      },
      async exprtPdf(id: string, sales_order_line_id: string): Promise<any> {
        try {
          const response = await asnApiService.exportPdf(
            id,
            sales_order_line_id,
          );
          if (!response) {
            throw response;
          }
          const url = response.data.preview_path;
          const a = document.createElement('a');
          document.body.appendChild(a);
          a.href = url;
          a.setAttribute('download', '');
          a.click();
          document.body.removeChild(a);
        } catch (error) {
          throw error;
        }
      },
      async getSavedColumnPreference(key: string) {
        const settings_store = useSettingStore();
        const saved_columns = await settings_store.getSetting(key) as dynamicObj;
        return String(!saved_columns ? '' : saved_columns);
      },
    },
  },
);
