<template>
  <q-input
    type="number"
    outlined
    dense
    v-model="params.shipped_quantity"
    @update:model-value="fetchData"
    :clearable="true"
    :debounce="1000"
    class="q-mr-sm"
    style="width: 227px; height: 40px"
  >
  </q-input>
</template>

<script lang="ts">
import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useDashboardShipmentStore } from 'src/pages/ShipmentOrder/store/index';
export default defineComponent({
  mixins: [],
  props: {},
  methods: {
    fetchData() {
      this.resetPagination();
      this.getAsnData();
    },
  },
  setup() {
    const store = storeToRefs(useDashboardShipmentStore());
    const { getAsnData, resetPagination } = useDashboardShipmentStore();
    const { params } = store;
    return {
      resetPagination,
      getAsnData,
      params,
    };
  },
});
</script>
