<template>
  <q-input
    :style="{ width: search_width ? search_width + '%' : '500px' }"
    dense
    v-model="params.item_id"
    autofocus
    :placeholder="$t('search_item_id')"
    outlined
    @keyup="onKeyup"
  >
    <template v-slot:append>
      <f-btn icon="tune" appearance="flat">
        <q-menu
          style="width: 500px; min-height: 250px"
          anchor="bottom start"
          self="top left"
          :offset="[453, 10]"
        >
          <div class="q-pa-md">
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{
                $t('po_number ')
              }}</span>
              <q-space />
              <PurchaseNumber />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{
                $t('shipped_quantity')
              }}</span>
              <q-space />
              <ShippedQuantity />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{
                $t('delivery_number')
              }}</span>
              <q-space />
              <DeliveryNumber />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{
                $t('location_id')
              }}</span>
              <q-space />
              <Warehouse />
            </div>
            <div class="row q-my-sm">
              <span style="margin-top: 5px">{{
                $t('doc_status')
              }}</span>
              <q-space />
              <Status />
            </div>
            <div class="float-right q-ml-auto">
              <f-btn
                appearance="secondary"
                class="q-mr-sm mt-20 q-mb-md"
                :label="$t('clear_filters')"
                @click="resetFilters()"
              />
            </div>
          </div>
        </q-menu>
      </f-btn>
    </template>
  </q-input>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useDashboardShipmentStore } from 'src/pages/ShipmentOrder/store/index';
import type { dynamicObj } from 'src/pages/assets';
import PurchaseNumber from 'src/pages/ShipmentOrder/components/filter/purchase_number-filter.vue';
import ShippedQuantity from 'src/pages/ShipmentOrder/components/filter/shipped_quantity-filter.vue';
import DeliveryNumber from 'src/pages/ShipmentOrder/components/filter/delivery_number-filter.vue';
import Warehouse from 'src/pages/ShipmentOrder/components/filter/warehouse-filter.vue';
import Status from 'src/pages/ShipmentOrder/components/filter/status-filter.vue';

export default defineComponent({
  mixins: [],
  props: {
    search_width: {
      type: Number,
    },
  },
  components: {
    PurchaseNumber,
    ShippedQuantity,
    DeliveryNumber,
    Warehouse,
    Status,
  },
  methods: {
    resetFilters() {
      this.resetFilter();
      this.fetchData();
      this.removeFiltersClass();
    },
    removeFiltersClass() {
      // remove sort class
      let elements = document.getElementsByClassName('orderBy selected');

      Array.from(elements).forEach((item: any) => {
        item.classList.remove('selected');
      });
    },
    onKeyup(event: any) {
      if (event.key == 'Enter') {
        this.fetchData();
      }
    },
    async fetchData() {
      this.loading = true;
      this.resetPagination();
      await this.getAsnData();
      this.loading = false;
    },

    handleEmptyStatus() {
      if (
        !(
          !this.searchInput ||
          this.searchInput === null ||
          this.searchInput.trim() === ''
        )
      ) {
        return false;
      }

      this.resetFilters();
      return true;
    },

    triggerApplyFilters() {
      const event = new CustomEvent('apply_filters', { detail: {} });
      document.dispatchEvent(event);
    },
  },
  setup() {
    const dashboard_store = useDashboardShipmentStore();
    const { loading, pagination, params } = storeToRefs(dashboard_store);
    const { getAsnData, resetPagination, resetFilter } = dashboard_store;

    return {
      getAsnData,
      pagination,
      loading,
      searchInput: ref(''),
      oldSearchInput: ref(''),
      showing: ref(false),
      debounceSearchInputFunc: {} as any,
      request_params: {} as dynamicObj,
      filter_data_json_str: '',
      resetPagination,
      resetFilter,
      params,
    };
  },
});
</script>
<style lang="scss">
.search-invoices {
  width: 500px;
  padding: 0;
  transition: 0.3s;
}
.user-select {
  width: 227px;
}
</style>
