<template>
  <MessageBanner
    v-if="!user_settings[shipment_order_dashboard]"
    :dissmiss_btn="false"
    :back_route="false"
    :message="$t('ACTION_NOT_ALLOWED')"
  />
  <template v-else-if="!isMobile()">
    <SubHeader
      name="shipment_order_dashboard"
      :label="$t('shipment_order_dashboard')"
    >
    </SubHeader>
    <div class="dashboard-container dashboard-text-color dashboard-main" data-test="shipment-order-dashboard">
      <DashboardHeader />
      <q-separator class="seperator" />
      <div class="full-width dashboard-list-area q-my-lg" style="overflow-x: auto;">
        <DocBitsTable
          :rows="tableRows"
          :columns="v2TableColumns"
          row-key="id"
          table-id="shipment_order_table"
          :loading="loading"
          :features="v2TableFeatures"
          :row-actions="v2RowActions"
          :pagination="v2PaginationState"
          :rows-per-page-options="[10, 20, 25, 50]"
          pagination-label="pagination_size"
          :pagination-settings-key="pagination_settings_key"
          no-data-label="no_record_found"
          :column-order="v2ColumnOrder"
          table-class="scroll-height-100vh-265px"
          @update:sorting="handleV2Sort"
          @update:pagination="handleV2Pagination"
          @column-reorder="handleV2ColumnReorder"
          @row-click="handleV2RowClick"
          @row-action="handleV2RowAction"
        >
          <!-- Purchase Order Column - with link style when PO exists -->
          <template #body-cell-purchase_order="{ row }">
            <span
              :class="row.purchase_order_id ? 'text-primary cursor-pointer' : ''"
              @click.stop="goToDetail(row.purchase_order_id)"
            >
              {{ row.purchase_order }}
            </span>
          </template>

          <!-- Shipped Quantity Column - centered -->
          <template #body-cell-shipped_quantity="{ row }">
            <div align="center">{{ row.shipped_quantity }}</div>
          </template>

          <!-- Line Number Column - centered -->
          <template #body-cell-line_number="{ row }">
            <div align="center">{{ row.line_number }}</div>
          </template>
        </DocBitsTable>
      </div>
    </div>
  </template>

  <q-inner-loading :showing="loading" style="z-index: 10000">
    <img class="loading-image" src="/images/loader.gif" alt="Loading..." />
  </q-inner-loading>
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { isMobile } from 'src/supplier/utils';
import type { dynamicObj } from 'src/pages/assets';
import { storeToRefs } from 'pinia';
import { ref, defineComponent } from 'vue';
import SubHeader from 'src/pages/Settings/Components/Sub-Header.vue';
import DashboardHeader from '../components/DashboardHeader.vue';
import MessageBanner from 'src/components/MessageBanner.vue';
import { DocBitsTable } from 'src/components/Table';
import { getSavedPaginationSize } from 'src/components/Table/PaginationSettings.vue';
import type {
  RowActionItem,
  SortEventPayload,
  PaginationChangePayload,
  RowActionPayload,
  RowClickPayload,
  UnifiedTableColumn,
} from 'src/components/Table';
import { useDashboardShipmentStore } from 'src/pages/ShipmentOrder/store/index';
import { useSettingStore } from 'src/store/Settings/setting.store';
import dragDropColumn from 'src/mixins/dragDropColumn';
import { ApiExceptions } from 'src/exceptions';
import generateSavedColumns from 'src/utils/generateSavedColumns';
import {
  supplier_dashboard_setting,
  shipment_order_dashboard_columns,
  CONSTANTS,
} from 'src/constants';

export default defineComponent({
  el: '#app',
  mixins: [dragDropColumn, generateSavedColumns],
  props: {
    type_name: {
      type: String,
      reqired: true,
      default: 'supplier',
    },
  },
  components: {
    SubHeader,
    MessageBanner,
    DashboardHeader,
    DocBitsTable,
  },
  data() {
    return {
      pagination_settings_key: 'SHIPMENT_PAGINATION_SIZE',
      supplier_dashboard_setting,
      show_table_loader: false,
      shipment_order_dashboard_columns,
      shipment_order_dashboard: CONSTANTS.shipment_order_dashboard,
    };
  },
  setup() {
    const dashboard_shipment_store = useDashboardShipmentStore();
    const { datePattern } = useSettingStore();
    const {
      loading,
      table_columns,
      display_data,
      paginationCount,
      params,
      pagination,
      sort_column,
    } = storeToRefs(dashboard_shipment_store);
    const { getAsnData, exprtPdf, getSavedColumnPreference } = dashboard_shipment_store;
    const settings_store = useSettingStore();
    const { user_settings } = storeToRefs(settings_store);
    const { updateSetting, startSettingsFetch } = settings_store;

    const tableColumns = ref();
    tableColumns.value = Object.values(
      JSON.parse(JSON.stringify(table_columns.value)),
    ).map((column: any) => {
      return {
        name: column.name,
        required: true,
        label: column.translation_key,
        field: column.name,
        actions: column.actions,
        align: column.align,
      };
    });

    return {
      loading,
      display_data,
      table_columns,
      getAsnData,
      paginationCount,
      tableColumns,
      user_settings,
      dashboard_shipment_store,
      searchInput: ref(''),
      params,
      current_page: ref(1),
      total_pages: ref(0),
      page_size: ref(5),
      total_records: ref(0),
      pagination,
      sort_column,
      isMobile,
      exprtPdf,
      datePattern,
      updateSetting,
      startSettingsFetch,
      getSavedColumnPreference,
    };
  },
  computed: {
    /**
     * Table rows from store display_data
     */
    tableRows(): dynamicObj[] {
      return Object.values(this.display_data);
    },

    /**
     * V2 Table: Transform table_columns to UnifiedTableColumn format
     */
    v2TableColumns(): UnifiedTableColumn[] {
      if (!this.tableColumns || this.tableColumns.length === 0) {
        return [];
      }

      // Apply saved order from user_settings if available, otherwise use tableColumns order
      const savedColumnsStr = this.user_settings?.[this.shipment_order_dashboard_columns];
      let orderedColumns = this.tableColumns;

      if (savedColumnsStr && savedColumnsStr !== '') {
        try {
          const savedColumns = JSON.parse(savedColumnsStr);
          const orderMap = new Map(savedColumns.map((col: any, index: number) => [col.name, index]));
          orderedColumns = [...this.tableColumns].sort((a: any, b: any) => {
            const aIndex = orderMap.get(a.name) ?? 999;
            const bIndex = orderMap.get(b.name) ?? 999;
            return (aIndex as number) - (bIndex as number);
          });
        } catch {
          // Use tableColumns order
        }
      }

      return orderedColumns.map((col: any) => ({
        name: col.name,
        label: this.$t(col.label || col.name),
        field: col.name,
        sortable: col.actions === true,
        align: (col.align || 'left') as 'left' | 'center' | 'right',
      }));
    },

    /**
     * V2 Table: Column order for persisted column reordering
     */
    v2ColumnOrder(): string[] {
      if (!this.tableColumns || this.tableColumns.length === 0) {
        return [];
      }

      // Apply saved order from user_settings if available
      const savedColumnsStr = this.user_settings?.[this.shipment_order_dashboard_columns];

      if (savedColumnsStr && savedColumnsStr !== '') {
        try {
          const savedColumns = JSON.parse(savedColumnsStr);
          return savedColumns.map((col: any) => col.name);
        } catch {
          // Use tableColumns order
        }
      }

      return this.tableColumns.map((col: any) => col.name);
    },

    /**
     * V2 Table: Feature configuration
     */
    v2TableFeatures() {
      return {
        sorting: true,
        filtering: false,
        selection: false,
        bulkActions: false,
        rowActions: true,
        resizable: false,
        pagination: true,
        columnReorder: true,
        columnSettings: true,
        stickyFirstColumn: false,
        stickyLastColumn: true,
      };
    },

    /**
     * V2 Table: Pagination state (includes sort info)
     */
    v2PaginationState() {
      return {
        sortBy: this.sort_column?.sort_by || null,
        descending: this.sort_column?.order === 'desc',
        page: this.pagination.current_page,
        rowsPerPage: this.pagination.page_size,
        rowsNumber: this.paginationCount || 0,
      };
    },

    /**
     * V2 Table: Row actions configuration
     */
    v2RowActions(): RowActionItem[] {
      return [
        { key: 'view', label: 'view', icon: 'visibility', color: 'primary' },
      ];
    },
  },
  mounted() {
    this.init();
    this.prepareTableColumns();
    this.initDragDropColumns('shipment_order_table', 'label');
    document.addEventListener(
      'shipment_order_table-column-drop',
      this.onDropColumns,
    );
  },
  unmounted() {
    document.removeEventListener(
      'shipment_order_table-column-drop',
      this.onDropColumns,
    );
  },
  methods: {
    // ========== V2 Table Event Handlers ==========
    async handleV2Sort(payload: SortEventPayload) {
      this.dashboard_shipment_store.sort_column.sort_by = payload.column;
      this.dashboard_shipment_store.sort_column.order = payload.direction;
      await this.getData(true);
    },

    async handleV2Pagination(payload: PaginationChangePayload) {
      this.pagination.current_page = payload.page;
      this.pagination.page_size = payload.rowsPerPage;
      await this.getData(true);
    },

    handleV2RowClick(payload: RowClickPayload) {
      this.goToDetail(payload.row.purchase_order_id);
    },

    async handleV2ColumnReorder(columnNames: string[]) {
      const columnsToSave = columnNames.map((name) => {
        const col = this.tableColumns.find((c: any) => c.name === name);
        return col;
      }).filter(Boolean);

      // Update local state immediately (prevents flicker during save)
      this.tableColumns = columnsToSave;
      this.user_settings[this.shipment_order_dashboard_columns] = JSON.stringify(columnsToSave);

      // Save to backend
      await this.savedOrderColumns(columnsToSave);
    },

    handleV2RowAction(payload: RowActionPayload) {
      if (payload.action === 'view') {
        this.goToDetail(payload.row.purchase_order_id);
      }
    },
    // ========== End V2 Table Event Handlers ==========

    async init() {
      this.startSettingsFetch();
      this.pagination.page_size = await getSavedPaginationSize(this.pagination_settings_key);
      this.getData(true);
    },

    prepareTableColumns() {
      // Apply saved column order from user_settings if available
      const savedColumnsStr = this.user_settings?.[this.shipment_order_dashboard_columns];
      if (savedColumnsStr && savedColumnsStr !== '') {
        try {
          const savedColumns = JSON.parse(savedColumnsStr);
          // Reorder tableColumns based on saved order
          const orderMap = new Map(savedColumns.map((col: any, index: number) => [col.name, index]));
          this.tableColumns = [...this.tableColumns].sort((a: any, b: any) => {
            const aIndex = orderMap.get(a.name) ?? 999;
            const bIndex = orderMap.get(b.name) ?? 999;
            return (aIndex as number) - (bIndex as number);
          });
        } catch {
          // Keep default order if parsing fails
        }
      }
    },

    onDropColumns() {
      this.savedOrderColumns(this.tableColumns);
    },

    async savedOrderColumns(columns: any) {
      try {
        this.loading = true;
        await this.updateSetting(
          this.shipment_order_dashboard_columns,
          JSON.stringify(columns),
        );
      } catch (err) {
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.loading = false;
      }
    },

    async getData(show_table_loader: boolean) {
      try {
        this.loading = true;
        if (show_table_loader) {
          this.show_table_loader = true;
        }
        await this.dashboard_shipment_store.getAsnData();
        this.total_records = this.paginationCount;
      } catch (error) {
        logError(error);
      } finally {
        this.loading = false;
        this.show_table_loader = false;
      }
    },

    openPurchaseOrderDetailsView(poNumber: string) {
      this.$router.push(`/purchase-order-detail/${poNumber}`);
    },

    goToDetail(po_number: string) {
      if (!po_number) return;
      this.$router.push(`/purchase-order-detail/${po_number}`);
    },

    includesDate(date: string) {
      const field = [
        'order_date',
        'requested_delivery_date',
        'estimated_delivery_date',
      ];
      return field.some((keyword) => date.includes(keyword));
    },

    includeStatus(status: string) {
      if (['Reserved', 'Allocated', 'Picking list printed'].includes(status)) {
        return 1;
      } else if (status === 'Delivered') {
        return 2;
      } else if (status === 'Invoiced') {
        return 3;
      }
    },

    resetFilters() {
      // remove sort class
      let elements = document.getElementsByClassName('orderBy selected');

      Array.from(elements).forEach((item: any) => {
        item.classList.remove('selected');
      });
    },

    async paginationItemClicked() {
      try {
        await this.getData(true);
      } catch (error) {
        logError(error);
      }
    },

    setRowStyle(row: any) {
      if (
        row.hasOwnProperty('export_data_fetched') &&
        row['export_data_fetched'] === true
      ) {
        return 'exported-row';
      }
    },
  },
});
</script>

<style scoped lang="scss">
// Styles inherited from dashboard-table-style in app.scss
</style>
