<template>
  <q-select
    outlined
    class="q-mr-sm"
    style="width: 227px; height: 40px"
    clearable
    dense
    v-model="params.status"
    :options="status"
    :label="$t('status')"
    @update:model-value="fetchData"
  >
    <template v-slot:selected-item="scope">
      <div>{{ scope.opt.label }}</div>
    </template>
  </q-select>
</template>

<script lang="ts">
// @ts-nocheck
import { defineComponent, ref } from 'vue';
import { PO_STATUSES } from 'src/pages/PurchaseOrders/constants.js';
import { useDashboardShipmentStore } from 'src/pages/ShipmentOrder/store/index';
import { storeToRefs } from 'pinia';
export default defineComponent({
  mixins: [],
  props: {},
  mounted() {
    this.initStatus();
  },
  unmounted: function () {
    // document.removeEventListener('reset_filters', this.resetFilters);
  },
  data() {
    return {
      status: [] as any,
      PO_STATUSES,
    };
  },
  methods: {
    fetchData() {
      this.resetPagination();
      this.getAsnData();
    },
    initStatus() {
      this.status = [];
      for (const [key, item] of Object.entries(this.PO_STATUSES)) {
        this.status.push({
          label: this.$t(item.label),
          value: item.value,
        });
      }
    },
  },
  setup() {
    const store = storeToRefs(useDashboardShipmentStore());
    const { getAsnData, resetPagination } = useDashboardShipmentStore();
    const { params } = store;
    return {
      params,
      getAsnData,
      resetPagination,
    };
  },
});
</script>
<style lang="scss">
.select-box.doc-type-select {
  max-width: 260px;
}
</style>
