<template>
  <div class="row q-mb-md">
    <div
      style="margin-top: 39px"
      class="row items-start example-container dashboard-title dark-readable"
    >
      <div
        class="example-cell cursor-pointer"
        tabindex="0"
        @click="refreshFilters"
      >
        {{ $t('all') }} {{ `(${total_data})` }}
      </div>
    </div>

    <div class="col q-ml-xl">
      <div class="row justify-start">
        <div class="dashboard-search-box q-ml-md mt-20 white-inputs">
          <quickSearch />
        </div>
        <q-space />
        <f-btn
          square
          class="q-mr-sm mt-20"
          @click="refreshFilters"
        >
          <Icon icon="mdi:refresh" width="20" height="20" />
          <q-tooltip>{{ $t('refresh_list') }}</q-tooltip>
        </f-btn>
      </div>
    </div>
  </div>
</template>
<script lang="ts">

import { defineComponent, ref } from 'vue';
import { storeToRefs } from 'pinia';
import { useDashboardShipmentStore } from 'src/pages/ShipmentOrder/store/index';
import type { dynamicObj } from 'src/pages/assets';
import quickSearch from './filter/quick-search.vue';
export default defineComponent({
  props: {
    type_name: {
      type: String,
      reqired: true,
      default: 'supplier',
    },
    media_screen: {
      type: String,
      reqired: true,
      optional: false,
    },
  },
  components: {
    
    quickSearch,
  },
  mounted() {
    document.addEventListener('delete_input_text', this.clearSearchInput);
  },
  methods: {
    clearSearchInput() {
      this.searchInput = '';
    },
    refreshFilters() {
      this.resetFilters();
      this.getDataServer();
      this.removeFiltersClass();
    },
    async getDataServer() {
      try {
        this.loading = true;
        await this.getAsnData();
        this.total_records = this.paginationCount;
      } catch (err) {
        logError(err);
      } finally {
        this.loading = false;
      }
    },
    resetFilters() {
      const event = new CustomEvent('reset_filters', {});
      document.dispatchEvent(event);
      this.resetFilter();
    },
    removeFiltersClass() {
      // remove sort class
      let elements = document.getElementsByClassName('orderBy selected');

      Array.from(elements).forEach((item: any) => {
        item.classList.remove('selected');
      });
    },
  },
  setup() {
    const dashboard_shipment_store = useDashboardShipmentStore();
    const {
      loading,
      display_data,
      params,
      pagination,
      paginationCount,
      total_data,
    } = storeToRefs(dashboard_shipment_store);
    const { getAsnData, resetFilter } = dashboard_shipment_store;
    return {
      getAsnData,
      loading,
      searchInput: ref(''),
      paginationCount,
      display_data,
      params,
      resetFilter,
      pagination,
      total_records: ref(0),
      total_data,
    };
  },
});
</script>
